\u0047\u0078\u007b\u0058\u0051\u0049\u0025\u0062\u0023\u0034\u0058\u0061\u0064\u004f\u0026\u0035\u0020\u0039\u0042\u004b\u0045\u0037\u0055\u0060\u004f\u0068\u0049\u0058\u0044\u002e\u0077\u007e\u0064\u0076\u006f\u006b\u007e\u0063\u002b\u007e\u002a\u005c\u0065\u0022\u0025\u0030\u005d\u0051\u0034\u005e\u002d\u0051\u0055\u0072\u0054\u003f\u0031\u003d\u0049\u006b\u0042\u0029\u0034\u0059\u0036\u007e\u0027\u004b\u0036\u003b\u0029\u003a\u004f\u0038\u0049\u004d\u0049\u0037\u0062\u0029\u002f\u0065\u0079\u003e\u005a\u004f\u0032\u007e\u0061\u0057\u005a\u0063\u003a\u0047\u0025\u0036\u004c\u007d\u007d\u0056\u0061\u0064\u0069\u005b\u0079\u002e\u0022\u004a\u005d\u0047\u003a\u0020\u002f\u0049\u0059\u0036\u0050\u0042\u0027\u006e\u0056\u005f\u0046\u0039\u0063\u004d\u0024\u0041\u0023\u003f\u006f\u0023\u003f\u0078\u0072\u006c\u0063\u0029\u0072\u0074\u0071\u0076\u0050\u0052\u0041\u004b\u0071\u0030\u003d\u0047\u004c\u003d\u005c\u0077\u0065\u0058\u0043\u004f\u0035\u006a\u0034\u006a\u005e\u0058\u006f\u0029\u0057\u004c\u0022\u0064\u0079\u0058\u0045\u0032\u0036\u0035\u005c\u0024\u006e\u0072\u0044\u007c\u002f\u0057\u0021\u0049\u0020\u0046\u006c\u0077\u0033\u0029\u0077\u007a\u0058\u0074\u003b\u0054\u0060\u0067\u0028\u003d\u0029\u002a\u0077\u003c\u0023\u004f\u004d\u0063\u0037\u0023\u002c\u0060\u0077\u0058\u0063\u003a\u0076\u0047\u0025\u0029\u002f\u0073\u0058\u0055\u002b\u0023\u004a\u0033\u0024\u003a\u006e\u0070\u006b\u0053\u0069\u002d\u0054\u0072\u0023\u0069\u002f\u0069\u0021\u0026\u007a\u0026\u0043\u0039\u0072\u0044\u0059\u0067\u007e\u0041\u0073\u0043\u0033\u0027\u004b\u0034\u0068\u0061\u002f\u003f\u003d\u003f\u0027\u0025\u0024\u0078\u003a\u004b\u002b\u005e\u0076\u003a\u006e\u0079\u0052\u0046\u0029\u004f\u004d\u0076\u0041\u003b\u002c\u004d\u0065\u003b\u0063\u0031\u0063\u0070\u006f\u002e\u003e\u0044\u0056\u0042\u003e\u003a\u0045\u005e\u0028\u0021\u0027\u005b\u005f\u0034\u0021\u0039\u004c\u004d\u003b\u0027\u0027\u0020\u003d\u0079\u0035\u0048\u0069\u006c\u0066\u003a\u0077\u0079\u0042\u0068\u0029\u0048\u0079\u007d\u007e\u0040\u0045\u002b\u0030\u007a\u0060\u0042\u004b\u006a\u0065\u007e\u006f\u0058\u0077\u003b\u0050\u0058\u002a\u0038\u002e\u0035\u0058\u0039\u0064\u0069\u0023\u007b\u0035\u0046\u0034\u0076\u005a\u0074\u0024\u0020\u0020\u007e\u007e\u005e\u0036\u0070\u0040\u005b\u0045\u0049\u007d\u004f\u003e\u0063\u0033\u0063\u0073\u006c\u007b\u0023\u0054\u006b\u0039\u0063\u0046\u005c\u0066\u0069\u0023\u0033\u0061\u002f\u002f\u0029\u006e\u005d\u0073\u0068\u0075\u0042\u005d\u0041\u0038\u0023\u0070\u0023\u007c\u0035\u0071\u0051\u003f\u0063\u0060\u0054\u002a\u006d\u0068\u0038\u0065\u0039\u007d\u0059\u0079\u0029\u0060\u004a\u0060\u0071\u0029\u0037\u006f\u0053\u006b\u0059\u0024\u004b\u0065\u0021\u0027\u005c\u0058\u0079\u0046\u0022\u0021\u0040\u0053\u006e\u0077\u003d\u002c\u003b\u0063\u0064\u0044\u006b\u0051\u005c\u004e\u006c\u0041\u006a\u002d\u0052\u0053\u0046\u0043\u0058\u002d\u0054\u004e\u0070\u0032\u0064\u003f\u0074\u0068\u0046\u0045\u0071\u007a\u0049\u0060\u006a\u005b\u002a\u003a\u0056\u004e\u004a\u004a\u0031\u0030\u0062\u0026\u002b\u002b\u005e\u0022\u0056\u0024\u007b\u005a\u007b\u007e\u0022\u0062\u0060\u0071\u005e\u0072\u005f\u0034\u0079\u0077\u006f\u007e\u0049\u0066\u0045\u0023\u0061\u0078\u0022\u0066\u007d\u0031\u007d\u006f\u0078\u0053\u0077\u0026\u0053\u003f\u0022\u0074\u0059\u0047\u005b\u0021\u005a\u0067\u007d\u0032\u007e\u0074\u0028\u005b\u0046\u006a\u0027\u0059\u007a\u0055\u0077\u006b\u005f\u002f\u006e\u005e\u0042\u0075\u0062\u0075\u007a\u0046\u0064\u0076\u006e\u004a\u0035\u005b\u005a\u002c\u0022\u0029\u004a\u003f\u0070\u005b\u0064\u0069\u006c\u005a\u0024\u002b\u0024\u002e\u003c\u003f\u0022\u0076\u0074\u0056\u003e\u003f\u0049\u0047\u0023\u0025\u0022\u0066\u0076\u0050\u0079\u0045\u002f\u007b\u007b\u002e\u007c\u0029\u002b\u0022\u0064\u0034\u0020\u003c\u004f\u0044\u006f\u0034\u0036\u0053\u003f\u004b\u002e\u0054\u0038\u0030\u0050\u0066\u003a\u0079\u0079\u003d\u002c\u0020\u0076\u006f\u0048\u0025\u003b\u0044\u007a\u003b\u0069\u003c\u0059\u0052\u0028\u005d\u0022\u0035\u0047\u005e\u0027\u003a\u0035\u0022\u006e\u004b\u0038\u006f\u0069\u0030\u0045\u007a\u0066\u003b\u003b\u0075\u004a\u0046\u0070\u0050\u007b\u0051\u0033\u0079\u003b\u0050\u0061\u0030\u0064\u0030\u0023\u0064\u0048\u0050\u0026\u0064\u0034\u0034\u0051\u0077\u005c\u0054\u0060\u0070\u0071\u002c\u0037\u003a\u0039\u0049\u0076\u003e\u007e\u0034\u0071\u0032\u005f\u005b\u0022\u004e\u006c\u0033\u0073\u0075\u0075\u006b\u0044\u0076\u0068\u0075\u002f\u0052\u004c\u006c\u0026\u0072\u002a\u0039\u004a\u006f\u006f\u0057\u0055\u0077\u006d\u0077\u005b\u0075\u0056\u0040\u0076\u0078\u0068\u0050\u004e\u006f\u0044\u005d\u0060\u005c\u0025\u007c\u0072\u0067\u0039\u002e\u0057\u0051\u0078\u0052\u003e\u0035\u002f\u0025\u0024\u002a\u006e\u0074\u0039\u0020\u005f\u006a\u0028\u005c\u0065\u0045\u003f\u0068\u0052\u0020\u002f\u002e\u0022\u0067\u005b\u0043\u005e\u0032\u0066\u0068\u0069\u006e\u0039\u0029\u005c\u004e\u006d\u006d\u002e\u0021\u0079\u0042\u002d\u0062\u0070\u004b\u0078\u0051\u0079\u0047\u0060\u0048\u0070\u003b\u0032\u0042\u004f\u0042\u003e\u002e\u0023\u0051\u0067\u0047\u0054\u004e\u007c\u0075\u002b\u002b\u0068\u0044\u007e\u0069\u006e\u0025\u004d\u0053\u002d\u002b\u002f\u0049\u0070\u0076\u002b\u003f\u002a\u0045\u0038\u0061\u0030\u0055\u0037\u0053\u002c\u0051\u0045\u0031\u002e\u0061\u0036\u0049\u004a\u0077\u007e\u005e\u0046\u0066\u007d\u0038\u002b\u0034\u002e\u006e\u007a\u0032\u0032\u005e\u0074\u0069\u0071\u0052\u0047\u004d\u0035\u0051\u0038\u0052\u0037\u0046\u005e\u0035\u005b\u007b\u0049\u006d\u0068\u0043\u0031\u0039\u0034\u0044\u0029\u0033\u003c\u0045\u0023\u007d\u0078\u005d\u003e\u0054\u0026\u004a\u004c\u0074\u0075\u0032\u003d\u005a\u0034\u0046\u0040\u004c\u002a\u0054\u004c\u002c\u002d\u006f\u0074\u0049\u0021\u006e\u0073\u002d\u0053\u0026\u004a\u0058\u003b\u0059\u002b\u0045\u0026\u0030\u0074\u002e\u0055\u005d\u005f\u006b\u007a\u0040\u0059\u006d\u004c\u0051\u003f\u0034\u007a\u0038\u002a\u0070\u0069\u0028\u002c\u006f\u0053\u003f\u0040\u006f\u003e\u0061\u003c\u0079\u003f\u007c\u0047\u0078\u0066\u004e\u004d\u0025\u0067\u004b\u0061\u005c\u0048\u0060\u006a\u0032\u0028\u0038\u0050\u004b\u0069\u0027\u002a\u005b\u0021\u007b\u004b\u003e\u0054\u0037\u0042\u0075\u0031\u004b\u006e\u0069\u007b\u0028\u007b\u004f\u003a\u006b\u0071\u0043\u003d\u0072\u003e\u0031\u005a\u0020\u0035\u0065\u0060\u0022\u004d\u0036\u004a\u0075\u005b\u0077\u007a\u002f\u005b\u0074\u0063\u006d\u003f\u0074\u007d\u0066\u0047\u0022\u006c\u003a\u007b\u0040\u007e\u005d\u006f\u007c\u0057\u0061\u0052\u0076\u0030\u002f\u0066\u0066\u006f\u0057\u0039\u0048\u004e\u005c\u0029\u0042\u004d\u0069\u004f\u0074\u0033\u006b\u0031\u003c\u007e\u0049\u0038\u0077\u0064\u0023\u0028\u0027\u0077\u006d\u003d\u0045\u003e\u0069\u005c\u002f\u0020\u0030\u005c\u004f\u0041\u006d\u004e\u0046\u005b\u0032\u007e\u006e\u0024\u0052\u0066\u005f\u0062\u002a\u0023\u0048\u0073\u0030\u0029\u007b\u0073\u003d\u0023\u0071\u002b\u0034\u0021\u0030\u0055\u002e\u0029\u004f\u0046\u005b\u005a\u0024\u0053\u0061\u0077\u0065\u004f\u0043\u0065\u004f\u004d\u005f\u003b\u0064\u0070\u0025\u003e\u006d\u0047\u004b\u0071\u003e\u0066\u0029\u0074\u0060\u0038\u0026\u002a\u0076\u0073\u0028\u006f\u003e\u0023\u004d\u006a\u0022\u002f\u006d\u006d\u0056\u0042\u0053\u0066\u006f\u0078\u0058\u0075\u005b\u0040\u0051\u0065\u0038\u0048\u0024\u003f\u006e\u0048\u0035\u0032\u0051\u004d\u002e\u0028\u007c\u0073\u0025\u0041\u0068\u003b\u0070\u0034\u0076\u006c\u005c\u007d\u0070\u006b\u005c\u0047\u007e\u002f\u0077\u0052\u004a\u0072\u0061\u0072\u007d\u0039\u0043\u0054\u007b\u0075\u006e\u0067\u0047\u0049\u007a\u004a\u006d\u0068\u0061\u007a\u0058\u003b\u0079\u0059\u0071\u0037\u005d\u003f\u0075\u003c\u0025\u005a\u0069\u0079\u004b\u0075\u002e\u004c\u002f\u0040\u002d\u0077\u0026\u006d\u0032\u0031\u0022\u0066\u006c\u005b\u0061\u004e\u0077\u005e\u006f\u0072\u005e\u005b\u0041\u004c\u002e\u005a\u0027\u0066\u0072\u0027\u0039\u0020\u0060\u0071\u0064\u003b\u0071\u0029\u0047\u004c\u004c\u0076\u0038\u0063\u0044\u004d\u0030\u0043\u004b\u0024\u0079\u0052\u002d\u0041\u0034\u0022\u003e\u003d\u0070\u003c\u007b\u007a\u0078\u0040\u0054\u0025\u0070\u0079\u0031\u0070\u0076\u005e\u005e\u0050\u003f\u0074\u0045\u0022\u0025\u003a\u0053\u0029\u0051\u0038\u0052\u003a\u005a\u005a\u0036\u003a\u007a\u0045\u0049\u0066\u004e\u0079\u0023\u0067\u0072\u0025\u003f\u0075\u0021\u005a\u0051\u0058\u004d\u004a\u0053\u0076\u0052\u0054\u0044\u0053\u005c\u007d\u0064\u0024\u003d\u0065\u0044\u0072\u0043\u006d\u004b\u0053\u0061\u007e\u007d\u004f\u0049\u004e\u006d\u0025\u0025\u003e\u007d\u0057\u0060\u006e\u0028\u0039\u004d\u007e\u005c\u0052\u003e\u0067\u005a\u0037\u0038\u0074\u0051\u004c\u0037\u0026\u002c\u003c\u003e\u0068\u0028\u006e\u0040\u0078\u0078\u006c\u0030\u0073\u0049\u006f\u0052\u006d\u003c\u003a\u0047\u005f\u007e\u0033\u007a\u0030\u0022\u003d\u0075\u006f\u0062\u0052\u002a\u007a\u0040\u0025\u0038\u005e\u006b\u0038\u006c\u0042\u0049\u0051\u0032\u002e\u0065\u0059\u0061\u0059\u0055\u0049\u006e\u005b\u005a\u006c\u0079\u0036\u006f\u003c\u0059\u0072\u0062\u0065\u0056\u004d\u007d\u0044\u003a\u003e\u0029\u0058\u0035\u007c\u005b\u0062\u0074\u0047\u0033\u0061\u006c\u0039\u0046\u004f\u0042\u0026\u006a\u006d\u0036\u007b\u006f\u0057\u0025\u0075\u0077\u0061\u007d\u007b\u005e\u0042\u0079\u0032\u0042\u0045\u0032\u0025\u003c\u0025\u0023\u002f\u0050\u005a\u0022\u0021\u005b\u0033\u0066\u0068\u0053\u0074\u0065\u0055\u0030\u0055\u0070\u0064\u0039\u005f\u004b\u003d\u006f\u0044\u0074\u0075\u0054\u002b\u0044\u007d\u0070\u0050\u0030\u0054\u005e\u0020\u0079\u002e\u0043\u007d\u0058\u0061\u004c\u0041\u004b\u0029\u002d\u0062\u004c\u0075\u0060\u0030\u0075\u0043\u0066\u0069\u0035\u002f\u0033\u006f\u0061\u004d\u004f\u0028\u0078\u004c\u0046\u0045\u004f\u002d\u007b\u003a\u006b\u0036\u005b\u003b\u0027\u0034\u0056\u0044\u006d\u004f\u0039\u0058\u0059\u0035\u0056\u003a\u0033\u0036\u0029\u0039\u0071\u003d\u0074\u0024\u0052\u003c\u0056\u003b\u0055\u0030\u0028\u003b\u0043\u0078\u004c\u0020\u0035\u007d\u0067\u0027\u007e\u0069\u0075\u0045\u006e\u0061\u0063\u007d\u0042\u0060\u0077\u0042\u0022\u002e\u003b\u0070\u0072\u005e\u0023\u0033\u0040\u0078\u0059\u0040\u0077\u0048\u002f\u0068\u003c\u003d\u0026\u0075\u004a\u004b\u007b\u0046\u0077\u003f\u0069\u0026\u0045\u0033\u005c\u0062\u004c\u0036\u003a\u004a\u0035\u0062\u0023\u0073\u0028\u0073\u0067\u0029\u006f\u0056\u0072\u0056\u003b\u0024\u006e\u004a\u0028\u0057\u0022\u0079\u0056\u0056\u004e\u007a\u0056\u002a\u002a\u0043\u0031\u0022\u0062\u0050\u0026\u0052\u0058\u0050\u0026\u0054\u0063\u0027\u0020\u005f\u0027\u0064\u0043\u004b\u0039\u0029\u003a\u0071\u004e\u007b\u0024\u0058\u003a\u0071\u0077\u0061\u0065\u004b\u0021\u0062\u006f\u0076\u006b\u004a\u0022\u0042\u002d\u006c\u0078\u0054\u0047\u0033\u002b\u0061\u0044\u0066\u005f\u0039\u0068\u004b\u0038\u006b\u0047\u0055\u0045\u0040\u002f\u0043\u0068\u0064\u0062\u0044\u006d\u0057\u0030\u0055\u0020\u003c\u0068\u0037\u0076\u0079\u0061\u0064\u0078\u006f\u0035\u0041\u0066\u0054\u0038\u004f\u0070\u007d\u0028\u0041\u006e\u005f\u0045\u003b\u003d\u0029\u0026\u007e\u006f\u003e\u0062\u005f\u0062\u003b\u004a\u005c\u004b\u0045\u003b\u0062\u0029\u0046\u003f\u0030\u0022\u0030\u002a\u0027\u0037\u0063\u007e\u0043\u0067\u0021\u0045\u0042\u0055\u0061\u0038\u004e\u0050\u0040\u0034\u0041\u0076\u0038\u002a\u005e\u002f\u0052\u006f\u004f\u005c\u0026\u0077\u0029\u0058\u0040\u0058\u007d\u0051\u006f\u0030\u0077\u0052\u0075\u0050\u0033\u005c\u006f\u003a\u005a\u002f\u0025\u0027\u004b\u002b\u0066\u0067\u004b\u0057\u005c\u0036\u004c\u0064\u0046\u0069\u0060\u004d\u0043\u007c\u002c\u0030\u0049\u0024\u0023\u0065\u004a\u0039\u0057\u0020\u0025\u0065\u0078\u0066\u0052\u003d\u002b\u0074\u0055\u003f\u007c\u003a\u0069\u0047\u0067\u0035\u004a\u0070\u003c\u002d\u0032\u003d\u0022\u007a\u0060\u007a\u0057\u007e\u0022\u004f\u0022\u0056\u0027\u005b\u006f\u0062\u005a\u0079\u0040\u0055\u002b\u004b\u007d\u005d\u0030\u0064\u0064\u0071\u006a\u006b\u0075\u0024\u007d\u0072\u0032\u003c\u005a\u005b\u005f\u002d\u0043\u0069\u0024\u003a\u004a\u006d\u0067\u0076\u0073\u002d\u0037\u0042\u0076\u0033\u004c\u0033\u0046\u006b\u0021\u003e\u005e\u002d\u003d\u003a\u006d\u0039\u0070\u0058\u0046\u0071\u0078\u0032\u002c\u0034\u006e\u006e\u0060\u0047\u0051\u0073\u004f\u0074\u0050\u0050\u0076\u007b\u005f\u002e\u006c\u005d\u002a\u0046\u0051\u0065\u005e\u0038\u006e\u0037\u004f\u0022\u0031\u0040\u003b\u0038\u007d\u0021\u003d\u0042\u0033\u003f\u005b\u0043\u0056\u007d\u0047\u0040\u004c\u007d\u003d\u0077\u0064\u0055\u0060\u0022\u0023\u004c\u0074\u0063\u0037\u0049\u0043\u006b\u003a\u007c\u005f\u0020\u004b\u0024\u006a\u0023\u005f\u0063\u0069\u0030\u0025\u0052\u0051\u005c\u006d\u0074\u0075\u0061\u0063\u0056\u0046\u0030\u0074\u0079\u006c\u0076\u004e\u0073\u0075\u0078\u002d\u003d\u0070\u0056\u0061\u006b\u0029\u0056\u0033\u0023\u0032\u0066\u0051\u0032\u007a\u0021\u002d\u0062\u0069\u007a\u006d\u007d\u003c\u0049\u0028\u0061\u0023\u0023\u0040\u0038\u007b\u006b\u0050\u0024\u0059\u006d\u004e\u0063\u0049\u005c\u005f\u007d\u0024\u005c\u0051\u0039\u0025\u0060\u002e\u0056\u0065\u0041\u0067\u005d\u0031\u004a\u004a\u004f\u0022\u004c\u0026\u0076\u0062\u0042\u0041\u0032\u007e\u0059\u0041\u0064\u003f\u0068\u0029\u0078\u007c\u0024\u0020\u0063\u0065\u0062\u006f\u0060\u0067\u0037\u002f\u0079\u005b\u007b\u0051\u0026\u0042\u0070\u0045\u0036\u005d\u006c\u007d\u0053\u0055\u0038\u0052\u0036\u0058\u005e\u007b\u0077\u0042\u0050\u0022\u0048\u005c\u0051\u003e\u004a\u0071\u003e\u002d\u0029\u0065\u005d\u005f\u007c\u0033\u0066\u006a\u002e\u0051\u0040\u0046\u0026\u0025\u0028\u005e\u004d\u006c\u0056\u004f\u005d\u0031\u007b\u0020\u0075\u007d\u0047\u0024\u0031\u002e\u006f\u0076\u0066\u0067\u0073\u007d\u0029\u002b\u0077\u007c\u0051\u0036\u0047\u0032\u0057\u0071\u0065\u0069\u0065\u0037\u002c\u004e\u0028\u005e\u0039\u0033\u0029\u0052\u0050\u0034\u004f\u0028\u003a\u0075\u0056\u0031\u005d\u0068\u0057\u004d\u007a\u003c\u002d\u0052\u0079\u0067\u0051\u003f\u004b\u0037\u003d\u0043\u003a\u0032\u0078\u0026\u005f\u0021\u005c\u0033\u0065\u006a\u0040\u0071\u0056\u0069\u0021\u0048\u0020\u007e\u0064\u0030\u003e\u0064\u0025\u004a\u0031\u0038\u0070\u0077\u0020\u0077\u006e\u003e\u0065\u007a\u003e\u006e\u0025\u0023\u0049\u0053\u0054\u004e\u0023\u0029\u0020\u0022\u0032\u002f\u0042\u005c\u0035\u007a\u003b\u002e\u0043\u0040\u0069\u005f\u0061\u006c\u0052\u002f\u0077\u003b\u004d\u005f\u003d\u006d\u004e\u002d\u006d\u0048\u002b\u003f\u003e\u0027\u0052\u0045\u0028\u0051\u0068\u002f\u0029\u0044\u0077\u0070\u0048\u002b\u0057\u0056\u0063\u005d\u007b\u0066\u0045\u0059\u003e\u0066\u0037\u002d\u0034\u007a\u0044\u003f\u0028\u003e\u0037\u0066\u0056\u002d\u005c\u0025\u0027\u003e\u0052\u003e\u0030\u0021\u0051\u0020\u006d\u007a\u007d\u0023\u005d\u0053\u0022\u005d\u0028\u006e\u004e\u0076\u007c\u0076\u003a\u003b\u0039\u0032\u005c\u002d\u0071\u002a\u004e\u006a\u0056\u005a\u0069\u007b\u0047\u002e\u0028\u003b\u0056\u0034\u003e\u003b\u006a\u0044\u0056\u003b\u0074\u003d\u006a\u0055\u005d\u0043\u003e\u0062\u0030\u003c\u0067\u003d\u007e\u002a\u0028\u0041\u0032\u0066\u0057\u0053\u003b\u0023\u0037\u0021\u0060\u0062\u0020\u005f\u006a\u006f\u0041\u0028\u006d\u0071\u005d\u0064\u007b\u003b\u0030\u007d\u0067\u0030\u004d\u005f\u007a\u007d\u003f\u0058\u004b\u0079\u0037\u0063\u0028\u0032\u0077\u0065\u005d\u0070\u0029\u002a\u002a\u0055\u0038\u0061\u005f\u0064\u006c\u002b\u0064\u0072\u0022\u007e\u0063\u0061\u006a\u0028\u0038\u0071\u003f\u0029\u004a\u003b\u0060\u0028\u0068\u0053\u0053\u0020\u004e\u0039\u003e\u0029\u0074\u0022\u006d\u0040\u002a\u0032\u006e\u0063\u0063\u0061\u0056\u004d\u0047\u007d\u002b\u003f\u0064\u0075\u005d\u004f\u0031\u006d\u0022\u0029\u006a\u006c\u0020\u005e\u005e\u0037\u004b\u0046\u0040\u0065\u002e\u0077\u0069\u0047\u007d\u0056\u0040\u0022\u0026\u006e\u0076\u003e\u0034\u004b\u0037\u0036\u0023\u0026\u0026\u0030\u0067\u002d\u0055\u0077\u0060\u0039\u002b\u002b\u006d\u0068\u0040\u002b\u0057\u0053\u0039\u0051\u006d\u0056\u006d\u0057\u005b\u002b\u006a\u007e\u0038\u0053\u0050\u0045\u0076\u0059\u005e\u005d\u0047\u005e\u0046\u0056\u0070\u0033\u0052\u0052\u0052\u0021\u0063\u0063\u002c\u0065\u0065\u0057\u004e\u0072\u0073\u0022\u0036\u0056\u0035\u006f\u0037\u0035\u0032\u0073\u0051\u002d\u0076\u002f\u005f\u004e\u005d\u0042\u0054\u005d\u0068\u0031\u0023\u0067\u0042\u0047\u0025\u0033\u0064\u0048\u0057\u0048\u0033\u0030\u003c\u0066\u0050\u0069\u006b\u0041\u005b\u0026\u005b\u003b\u0025\u005d\u0042\u0060\u0048\u0076\u004f\u0062\u0072\u002b\u002c\u0065\u0051\u002b\u0030\u0044\u0060\u007e\u002d\u0038\u0043\u0074\u0033\u0020\u0071\u0034\u0047\u004f\u005b\u0043\u0049\u006b\u003c\u0055\u0070\u0055\u003a\u0071\u003c\u003d\u0076\u002a\u0078\u0056\u0074\u003b\u0055\u004f\u0044\u005b\u0052\u004f\u0063\u0056\u0056\u006e\u0059\u0068\u0078\u0035\u0035\u0021\u005d\u0066\u0034\u0061\u006e\u002f\u002d\u0050\u0037\u0048\u0054\u003c\u0075\u0057\u0036\u0057\u0031\u0025\u0037\u004f\u002f\u004c\u0070\u0051\u0046\u0058\u0023\u0042\u005f\u005a\u0054\u0046\u0022\u003c\u0031\u0059\u0071\u0078\u0079\u0027\u007b\u006e\u007b\u0075\u0020\u002a\u007e\u0033\u0035\u004d\u007e\u0070\u0035\u0045\u0051\u006f\u0030\u004f\u006f\u0045\u004c\u0075\u0043\u0059\u0023\u004a\u0069\u0051\u0057\u0039\u006b\u0023\u0058\u006c\u0044\u003a\u0063\u0048\u002f\u0040\u0020\u006c\u0051\u006a\u0040\u003c\u0046\u0071\u0024\u0022\u002a\u0027\u0049\u006f\u004a\u0039\u0059\u0055\u004b\u005e\u0074\u002b\u0052\u0077\u0022\u006d\u0069\u0072\u0074\u006e\u006a\u0077\u005b\u0068\u0067\u0047\u0070\u0068\u004e\u006a\u007d\u0077\u0067\u0056\u0052\u0069\u0070\u002b\u004f\u0067\u005e\u0035\u003b\u004e\u002a\u004c\u0027\u0062\u005e\u002f\u005a\u003a\u0067\u0058\u0044\u0057\u0047\u005a\u0027\u007b\u003c\u0047\u0028\u0024\u006a\u0060\u0040\u0022\u0053\u0031\u0024\u0068\u002d\u0027\u0045\u0050\u0052\u0042\u006e\u0061\u006f\u0062\u0069\u003e\u003f\u0021\u0072\u006d\u002b\u0031\u0069\u0058\u007d\u0038\u0078\u0038\u006d\u0065\u0038\u004b\u002f\u002b\u005d\u007e\u0034\u004c\u0049\u002b\u0031\u004a\u007c\u0051\u0067\u0056\u0024\u0079\u0042\u0079\u0072\u0061\u0069\u0037\u0044\u006a\u0032\u006e\u002a\u002b\u0055\u0056\u0042\u005f\u0046\u004d\u0020\u002a\u0027\u002f\u0071\u005e\u0079\u0068\u006b\u0023\u0038\u0051\u0052\u0058\u0032\u0055\u006a\u007a\u0039\u0020\u0054\u0074\u002a\u0049\u004c\u0051\u0066\u006d\u007b\u002f\u0067\u003e\u0030\u006b\u0055\u007d\u005e\u0050\u002b\u0052\u007b\u0063\u0051\u0049\u0037\u0074\u0061\u0028\u0048\u0063\u007a\u0054\u0060\u0027\u0078\u0050\u0052\u004d\u0070\u004c\u003a\u0065\u007e\u0032\u0044\u005d\u006d\u0058\u0050\u0039\u0021\u0063\u0053\u0041\u0037\u006d\u0078\u0055\u002f\u007b\u0058\u007a\u0020\u0030\u0042\u0024\u0044\u0058\u004a\u0066\u002d\u0058\u003d\u0060\u002c\u0023\u0042\u0070\u0055\u0030\u0068\u0047\u0075\u0023\u003c\u0039\u0067\u0050\u0047\u0072\u0038\u0021\u002c\u004c\u007d\u0079\u0074\u0078\u005c\u003b\u0052\u0031\u0036\u0024\u0046\u0056\u0039\u005f\u0034\u0079\u0040\u0077\u0020\u0050\u0023\u0039\u0073\u0069\u0074\u0069\u0051\u005c\u0021\u0033\u0023\u0055\u0042\u0063\u0049\u0046\u003b\u005c\u0057\u0075\u004e\u0046\u0021\u0031\u007d\u0054\u0021\u004a\u003f\u0076\u0042\u0073\u0066\u004b\u0068\u003c\u006c\u0035\u007a\u004e\u003c\u0054\u0060\u0035\u003d\u0055\u007d\u002b\u0028\u0052\u004c\u003e\u007c\u0075\u0078\u0068\u0039\u004a\u007a\u0064\u0071\u0060\u0067\u003f\u0059\u0064\u0021\u0037\u0027\u0070\u002f\u003a\u006f\u0035\u0052\u0066\u0050\u0044\u0073\u006c\u007d\u0026\u0059\u006a\u005f\u005a\u0027\u0035\u004c\u0062\u004f\u0048\u005e\u0062\u0067\u0073\u005a\u005b\u003e\u005f\u0046\u0076\u003a\u007d\u0075\u0023\u0054\u005f\u003f\u0049\u0067\u0050\u002e\u0063\u003c\u0076\u007e\u0063\u002d\u007b\u0021\u0072\u0052\u0043\u0043\u006d\u0065\u0053\u0046\u0041\u0061\u0037\u0055\u0056\u0040\u0045\u005a\u0065\u0043\u0035\u004a\u0023\u004f\u004f\u0070\u004b\u0067\u006c\u0077\u0062\u0056\u0028\u0034\u0075\u0029\u0065\u0050\u004f\u0047\u004d\u0061\u0043\u0048\u0024\u005b\u0051\u0026\u0058\u0063\u0061\u0052\u004e\u0052\u0053\u0075\u0040\u007c\u0053\u006d\u004d\u003b\u0051\u0071\u0074\u006e\u0065\u0054\u006a\u007c\u004c\u003c\u007a\u0058\u0066\u0058\u0076\u002f\u0023\u002d\u003e\u0033\u0063\u004d\u002b\u003d\u0043\u0032\u003e\u0073\u0068\u0075\u0059\u007d\u0035\u0076\u0070\u005d\u0051\u005c\u007a\u0078\u0044\u0033\u005e\u004d\u0044\u004c\u0035\u0063\u0052\u007e\u0026\u0059\u0049\u0023\u0066\u006b\u006c\u0022\u004d\u0052\u0058\u006e\u0030\u0031\u004b\u0021\u0047\u0045\u0043\u005c\u0063\u0076\u0078\u0050\u0075\u004e\u005b\u006c\u006f\u0057\u0030\u0020\u006c\u0078\u0043\u007d\u0071\u0061\u0064\u0058\u0066\u0065\u005d\u007e\u005e\u0067\u004b\u005c\u0068\u004a\u0062\u0057\u0035\u0042\u0046\u0053\u0048\u007c\u005c\u0060\u0055\u0034\u0021\u0068\u0073\u0067\u0067\u0056\u0032\u0076\u0049\u0055\u0028\u0053\u0054\u0070\u0047\u0078\u007a\u0074\u0055\u0033\u004f\u0076\u005a\u0044\u005d\u0039\u004f\u006c\u0056\u0041\u0023\u0077\u0078\u0042\u0025\u0043\u0022\u004f\u0064\u007d\u0048\u005b\u002a\u0026\u0070\u004c\u0060\u0071\u0050\u0049\u0066\u0020\u0067\u002f\u0025\u007a\u0051\u0061\u0046\u002f\u0046\u0028\u005c\u0023\u0078\u0041\u0028\u0022\u0053\u0042\u0044\u0028\u0039\u0041\u0030\u004a\u0065\u005b\u0043\u0066\u0037\u0042\u0058\u003a\u004b\u0055\u006e\u002b\u0031\u0058\u0035\u0077\u003b\u003c\u0060\u0068\u0022\u003c\u0045\u006d\u007a\u0071\u0033\u0067\u003a\u0039\u0060\u0068\u002b\u0034\u0021\u006d\u0036\u003a\u0025\u0073\u0073\u006a\u0027\u0050\u003f\u0061\u0068\u0074\u0073\u0043\u0024\u006d\u0051\u007a\u0036\u0069\u005a\u0045\u0075\u003d\u004c\u0021\u0043\u006d\u0030\u0063\u0028\u0059\u005e\u003a\u0073\u0037\u006c\u004f\u006b\u007a\u002e\u007c\u005a\u0055\u0057\u0030\u0041\u006c\u0034\u0027\u0054\u006f\u007d\u0032\u0068\u0037\u0034\u0020\u0027\u0061\u0044\u007d\u006c\u006e\u002c\u0066\u005b\u0055\u0037\u006b\u0056\u0040\u0068\u002e\u007b\u0050\u006f\u003d\u0065\u0044\u0043\u0032\u0041\u0067\u0063\u006d\u005a\u007e\u0041\u0023\u002b\u0033\u0031\u0063\u005d\u002f\u0058\u0033\u0062\u002e\u0037\u0030\u0041\u004c\u006e\u0061\u0060\u0024\u0071\u0046\u006b\u0071\u0027\u0044\u0039\u0021\u005e\u003b\u0046\u0070\u0061\u002c\u0067\u007e\u0056\u003b\u0069\u0052\u0040\u0033\u0046\u0027\u002d\u0078\u004d\u0056\u003f\u0046\u005b\u005c\u005e\u0078\u006a\u0078\u0060\u004b\u004d\u0052\u005b\u0054\u0031\u005c\u0070\u004e\u0030\u0074\u0024\u007b\u003d\u0055\u0031\u004a\u0033\u0062\u004f\u006b\u0066\u003a\u0069\u004c\u0025\u0043\u0029\u0059\u0044\u0023\u0066\u004b\u0026\u0030\u002b\u003c\u0048\u0068\u0054\u0052\u0062\u0074\u0026\u006b\u0076\u003d\u004d\u002e\u0063\u0061\u0037\u007c\u002f\u0048\u0072\u0063\u0078\u0056\u007b\u0031\u002f\u0061\u0022\u006f\u003d\u004d\u0054\u005e\u004e\u003f\u006d\u0073\u0051\u0079\u0023\u0027\u0026\u0030\u002a\u0020\u0030\u0063\u006a\u006e\u0055\u0054\u0043\u0071\u004d\u004c\u005a\u002e\u003e\u007e\u0079\u005e\u0025\u0065\u0038\u0020\u0059\u0038\u005e\u002b\u0072\u005d\u0070\u0063\u0044\u0020\u0043\u0042\u0060\u0041\u004a\u0066\u0045\u0058\u005a\u004b\u0054\u0060\u0069\u0035\u0062\u005e\u0055\u0032\u007e\u0042\u0073\u007d\u0045\u0046\u0051\u0050\u006a\u0042\u005e\u0079\u0074\u0042\u004d\u0059\u0037\u0029\u0042\u0049\u007c\u002e\u0067\u0075\u0043\u0050\u0064\u0022\u0079\u002d\u005d\u0046\u0079\u0038\u003e\u003e\u0033\u004d\u0068\u0028\u006c\u0073\u0023\u006f\u0032\u0074\u0075\u002a\u0074\u0026\u0045\u003e\u0035\u005d\u0029\u0059\u0055\u0064\u006d\u002b\u0033\u0030\u0058\u0063\u006a\u0043\u006c\u0052\u0037\u005b\u0051\u002f\u003d\u0068\u0026\u003d\u0052\u005a\u007d\u003a\u005d\u007e\u0042\u0020\u0078\u0078\u0026\u005f\u0070\u0060\u002a\u0025\u007b\u0068\u0037\u005b\u007d\u0036\u007e\u0031\u004f\u003c\u005a\u0077\u003b\u004d\u0024\u0078\u0032\u0034\u0077\u0046\u004e\u0030\u0057\u0029\u0078\u0069\u006a\u0031\u006a\u006f\u0068\u0026\u0061\u0065\u005f\u0021\u0021\u0026\u0058\u006f\u003e\u0053\u0056\u005d\u0037\u0034\u0044\u003c\u0077\u0065\u0042\u0049\u0023\u0065\u0073\u003f\u0051\u0043\u0036\u0049\u0036\u007e\u0041\u005a\u0067\u0056\u0067\u0064\u0071\u006c\u0024\u0053\u002d\u0035\u0059\u0047\u0030\u004a\u007c\u005b\u0070\u0043\u0041\u0076\u0050\u0040\u0065\u0079\u0042\u0077\u0050\u007c\u0038\u004b\u0063\u003d\u0045\u003c\u0065\u0039\u005b\u005d\u0057\u0050\u0027\u0046\u0028\u0067\u0037\u005d\u0029\u007e\u005b\u003d\u0065\u003b\u0070\u0054\u0049\u0044\u002d\u0074\u0079\u0067\u0026\u0024\u0028\u003a\u0059\u0069\u0026\u0068\u0055\u002e\u0020\u005f\u0039\u0022\u0052\u005b\u0077\u0064\u002e\u0069\u0063\u0073\u006e\u002d\u0031\u0049\u0033\u0060\u0062\u0055\u0058\u0077\u0038\u0033\u0048\u006e\u0049\u002b\u0074\u005b\u0067\u0043\u002b\u0050\u004d\u0060\u002b\u0023\u0049\u0078\u0026\u0047\u006e\u0040\u002c\u006a\u0079\u0050\u005b\u0050\u0062\u004f\u0077\u0028\u0052\u005f\u003e\u0072\u0065\u005a\u002b\u0058\u0067\u006c\u005f\u0060\u006e\u007a\u0068\u0077\u0058\u0060\u0038\u0067\u0052\u0068\u0037\u0040\u0037\u0077\u0024\u0059\u0031\u0054\u0066\u0046\u002d\u006b\u0034\u007d\u0069\u0051\u005f\u0052\u0049\u0045\u004c\u0074\u0053\u0078\u0065\u003b\u003c\u0057\u006e\u007a\u0055\u0079\u0068\u0070\u002f\u0059\u003a\u004a\u002c\u0054\u0045\u002d\u006c\u0059\u0022\u0043\u0072\u007d\u0042\u002e\u0061\u004b\u0031\u0026\u004f\u003c\u0030\u0029\u007b\u0061\u0037\u0028\u0050\u0046\u0060\u0033\u003e\u0079\u0049\u0056\u0027\u007d\u0059\u0078\u0068\u002f\u004e\u0069\u0057\u0073\u0066\u0073\u006f\u002b\u0064\u002e\u003b\u0031\u0053\u0064\u0032\u0056\u002a\u007e\u0037\u004f\u0031\u0029\u005f\u0040\u007e\u002a\u0040\u002b\u006f\u0053\u0031\u005e\u0052\u0024\u004a\u0074\u0040\u0050\u006b\u005c\u0059\u0037\u0022\u007a\u005b\u0053\u002c\u003e\u0041\u0025\u0062\u0069\u0040\u0054\u0069\u005b\u0052\u006d\u0076\u0076\u002c\u0032\u006d\u004b\u0055\u007a\u004a\u0044\u0024\u006d\u0075\u005f\u005a\u0056\u002d\u005e\u0036\u0057\u0037\u0026\u0022\u0030\u0045\u0022\u003b\u0034\u007e\u002a\u0070\u003c\u007a\u0059\u0063\u003b\u003f\u003f\u0037\u003b\u0048\u0038\u0022\u0077\u0054\u004d\u004d\u0059\u0055\u002e\u0055\u005e\u0033\u002e\u0075\u0047\u0049\u0076\u002a\u0021\u0068\u0069\u0063\u005d\u0043\u003f\u0049\u006c\u004d\u0079\u002d\u0044\u005e\u0028\u0056\u002d\u004a\u007a\u0072\u0052\u0057\u0052\u006c\u006f\u005d\u0023\u004b\u0077\u003e\u0043\u0035\u0062\u0043\u003c\u0043\u006b\u003c\u0039\u007b\u003a\u0035\u0031\u0068\u0020\u0030\u0039\u0064\u004c\u007d\u0020\u006d\u0030\u0079\u0072\u0079\u004d\u0045\u0046\u0051\u0045\u0070\u006d\u0050\u006c\u0049\u0020\u006c\u0071\u004c\u005f\u004c\u005e\u004f\u0029\u004b\u0054\u0076\u0037\u0055\u007a\u006b\u004f\u0062\u002d\u002b\u003e\u005a\u0074\u007c\u002b\u0052\u003a\u005f\u006c\u005e\u0076\u0027\u002d\u0058\u002c\u0031\u003a\u004a\u006c\u003c\u003d\u0043\u007d\u0020\u0077\u0033\u002b\u0022\u0077\u0047\u0041\u002e\u0057\u007d\u003b\u004d\u0044\u0024\u004f\u004e\u0042\u006b\u0021\u0048\u0053\u0046\u004c\u002c\u0039\u0059\u0049\u0020\u0044\u0025\u0043\u003d\u002e\u0069\u005d\u0031\u0031\u002e\u002c\u002f\u005f\u005a\u007a\u0053\u003d\u0056\u006f\u006d\u0065\u0057\u002e\u0036\u004d\u0050\u006e\u0054\u005b\u004a\u0044\u003e\u002a\u0055\u0064\u0029\u002f\u0039\u006e\u0041\u003e\u004a\u0072\u0059\u003e\u0024\u0045\u0058\u0073\u006f\u002d\u0040\u006a\u007c\u0072\u003e\u0030\u002b\u007d\u0031\u007c\u004f\u0023\u0077\u0076\u0056\u0060\u0052\u0052\u006f\u005a\u0021\u002b\u002e\u0041\u005e\u0060\u006c\u003f\u0028\u005a\u0034\u0077\u0045\u0033\u0050\u0044\u003b\u004c\u007b\u0070\u0074\u0036\u0053\u003b\u0070\u0078\u006a\u003a\u0055\u005d\u0059\u0031\u005a\u003a\u0025\u0062\u0050\u006f\u0055\u0073\u0079\u002a\u0044\u0062\u0052\u0044\u007c\u0025\u004c\u0066\u0069\u003d\u0062\u0070\u0026\u0035\u0046\u0063\u0057\u0027\u0045\u0074\u002a\u0059\u0026\u0035\u0076\u0076\u0053\u0062\u0067\u003f\u0077\u0036\u0034\u002a\u0067\u0062\u0045\u0062\u0040\u004b\u0053\u0036\u004e\u007e\u0075\u004b\u003a\u0033\u0063\u0048\u0020\u0057\u0031\u0023\u0056\u0051\u0028\u0034\u0020\u0043\u003f\u0066\u0069\u0029\u0051\u006f\u0033\u0035\u0029\u0044\u0060\u007c\u0039\u0050\u006f\u007a\u0057\u0026\u0043\u0045\u0079\u0025\u0036\u0046\u0051\u0076\u004b\u007d\u005e\u0055\u0047\u0075\u0044\u0055\u0050\u0028\u006c\u0064\u0063\u007a\u005d\u0031\u0062\u0071\u0071\u0059\u006e\u005a\u0079\u0029\u0050\u006f\u0045\u0064\u005c\u0028\u0056\u0051\u0032\u0068\u006e\u0021\u006d\u0073\u0048\u0038\u007d\u007d\u0038\u0050\u006b\u003d\u0041\u0028\u002a\u005a\u0063\u0048\u005f\u0071\u002e\u0023\u0059\u0025\u0034\u0023\u0073\u0027\u003d\u0029\u004e\u0067\u006d\u007b\u0033\u0051\u0041\u007b\u0027\u0060\u004c\u0038\u0041\u002d\u0033\u002a\u006d\u0063\u005d\u0044\u002a\u0063\u0045\u0060\u004c\u0068\u006b\u0079\u0057\u0031\u006b\u0076\u0063\u0039\u007a\u0065\u0079\u004c\u0059\u0067\u0044\u0054\u0053\u0026\u0052\u0063\u0050\u007a\u0060\u006b\u002c\u003c\u002a\u0025\u0074\u0052\u007a\u005f\u004f\u0034\u0027\u004c\u0059\u006d\u007b\u0061\u0062\u0052\u0074\u0079\u002b\u0060\u005c\u007d\u0048\u004c\u0075\u005c\u004e\u006e\u006b\u0036\u003b\u007d\u0079\u005b\u007a\u006c\u002e\u0059\u0022\u0047\u0038\u002b\u0070\u0053\u006d\u0051\u007b\u0057\u0033\u0060\u003d\u007a\u0039\u0039\u0038\u005a\u0062\u0077\u0054\u0074\u0068\u0049\u0064\u002b\u005c\u0036\u0028\u0060\u005f\u0029\u0058\u0024\u003c\u0078\u0037\u0049\u0060\u0078\u002e\u0023\u002d\u0036\u005b\u002b\u007a\u0077\u003e\u0051\u0041\u003b\u0060\u0035\u0030\u0036\u005a\u005a\u0022\u005b\u0052\u0042\u007e\u0074\u004a\u0046\u004a\u0067\u0061\u0071\u0066\u0063\u003a\u005c\u0058\u0039\u0073\u0067\u0043\u0027\u0034\u0031\u0040\u0025\u002e\u0073\u0056\u0024\u0047\u0066\u0069\u0038\u0070\u004b\u0053\u003a\u0076\u007b\u0079\u0029\u003d\u006a\u0073\u0043\u004f\u0024\u0071\u0022\u0024\u0023\u004b\u005f\u002e\u0038\u0026\u0065\u006a\u005b\u005e\u0066\u005b\u003b\u003a\u0040\u0052\u0066\u0028\u0042\u0024\u0065\u0041\u0076\u0023\u0079\u0020\u0068\u004e\u0033\u003b\u004f\u003d\u003c\u004f\u0028\u005e\u0061\u006c\u0052\u0061\u005f\u004f\u0024\u004b\u0046\u0064\u004a\u0073\u002d\u0077\u006b\u0029\u0074\u0046\u0064\u005f\u0076\u0051\u0027\u005a\u002d\u005b\u004d\u0055\u0071\u006f\u0064\u0028\u0079\u004a\u0075\u002c\u0021\u0064\u0023\u005e\u0064\u002c\u005f\u003f\u0042\u0056\u003d\u0074\u0041\u007c\u0029\u0053\u004a\u005a\u0038\u0060\u007b\u0056\u0077\u002b\u0065\u003f\u003d\u006e\u0062\u0044\u0074\u0054\u003f\u0028\u0068\u005d\u0025\u0052\u005f\u004f\u0041\u0027\u004d\u004c\u0022\u0057\u0076\u0040\u006a\u0050\u0074\u0026\u0034\u003c\u004c\u006f\u0070\u002b\u002a\u0044\u0041\u002b\u0024\u002f\u0070\u002c\u0052\u0056\u005b\u0045\u0020\u006e\u0054\u0035\u005a\u0035\u0041\u0054\u0037\u003a\u0050\u0052\u0031\u0060\u006f\u006d\u0055\u002e\u0068\u0044\u002b\u0038\u0066\u0052\u006d\u005c\u0068\u0043\u0078\u0027\u0048\u007c\u0048\u0021\u003a\u006e\u0050\u007c\u003a\u003d\u0020\u0038\u0064\u0070\u006f\u0051\u0041\u0052\u003a\u0028\u0031\u003b\u0029\u0050\u0047\u0065\u0026\u002d\u0047\u0046\u0064\u007b\u002f\u0041\u0055\u0026\u0023\u0039\u0078\u004e\u0035\u0043\u0064\u0048\u0065\u0024\u0034\u0079\u0054\u0041\u005d\u0021\u0059\u006e\u006b\u002f\u0021\u0023\u0066\u002d\u0076\u005c\u0049\u002f\u0029\u0051\u002e\u0042\u007b\u003f\u004e\u005b\u002e\u0050\u005f\u004e\u005b\u0076\u0069\u0065\u0063\u0060\u005d\u006b\u0079\u0079\u003c\u0074\u004c\u0070\u0030\u0043\u005e\u0038\u003e\u003b\u003d\u0071\u002a\u004a\u0046\u0065\u0062\u003f\u0077\u0067\u007e\u0075\u0036\u007e\u0044\u0063\u006d\u0031\u0038\u0035\u002c\u0044\u002b\u0072\u0026\u0047\u002b\u0078\u002a\u0070\u0060\u003b\u0073\u0041\u007e\u0035\u0039\u0021\u0052\u0037\u0052\u0067\u004d\u004b\u0055\u0073\u0029\u0051\u004a\u006b\u003a\u005e\u005b\u0049\u003d\u002a\u005d\u0065\u0060\u005f\u003d\u005d\u005d\u0057\u0077\u0054\u002d\u0023\u004f\u0063\u0045\u0035\u004c\u005d\u0049\u0058\u0057\u0055\u004b\u0041\u0075\u002b\u0073\u0039\u0071\u006a\u0022\u0037\u0070\u0023\u006d\u004f\u003b\u003d\u0039\u0027\u007d\u005a\u005d\u0054\u0038\u005a\u0055\u004c\u0037\u002a\u0049\u0027\u0035\u0076\u0077\u0038\u005b\u007c\u0036\u0049\u0065\u0035\u0055\u0051\u0041\u0020\u003c\u0050\u0036\u005f\u003d\u0063\u0038\u0025\u006e\u002f\u0054\u003f\u0076\u007a\u0066\u0069\u0048\u0054\u005e\u0077\u0031\u0033\u0029\u0050\u0053\u0074\u0033\u002d\u006e\u0062\u0030\u002e\u0045\u0074\u0022\u0037\u0075\u0020\u0051\u007c\u003a\u004a\u006a\u0069\u0029\u0059\u0059\u0043\u0032\u0071\u0056\u0051\u0037\u0050\u005c\u003f\u0057\u0056\u0065\u0044\u0047\u005b\u0038\u0063\u0055\u0031\u0029\u007c\u005c\u003c\u0063\u0032\u0051\u0071\u0057\u002e\u006d\u0036\u0049\u0059\u004f\u0035\u007a\u0063\u004b\u0069\u0037\u006f\u003a\u003c\u002e\u006a\u0021\u0027\u006f\u0054\u003e\u002d\u0035\u0059\u0030\u005b\u0031\u002d\u004b\u005f\u002d\u0023\u0035\u0044\u004c\u007e\u0078\u005c\u0038\u005b\u004a\u0066\u0068\u0032\u0064\u0040\u0044\u0040\u0057\u007c\u0053\u003b\u002f\u0055\u005c\u0025\u0020\u0077\u0031\u0056\u0032\u006a\u0029\u0075\u0062\u005b\u0039\u0043\u0034\u005e\u005b\u0066\u0061\u0074\u0021\u0070\u0070\u006d\u002d\u007c\u003e\u0033\u0030\u002a\u0020\u0052\u0071\u002e\u0058\u006f\u0058\u003a\u0066\u005a\u004c\u0059\u0033\u007e\u006e\u0061\u0032\u007d\u0072\u003c\u005e\u0040\u0035\u0026\u0055\u004a\u003e\u004c\u0034\u002b\u004f\u0060\u0025\u005f\u0056\u0027\u004b\u0067\u006a\u0029\u0050\u0068\u0073\u006c\u004a\u006b\u0054\u0074\u0066\u0020\u0024\u004b\u0070\u0062\u0061\u0020\u0053\u006a\u005d\u003f\u0057\u0039\u0064\u0022\u0032\u0061\u0032\u0034\u0038\u0055\u0032\u0035\u005a\u0062\u0052\u0036\u006b\u007e\u0027\u0046\u0020\u006b\u006b\u0060\u0029\u0071\u0024\u005b\u0024\u0040\u003d\u0045\u0072\u0067\u0043\u005c\u0060\u0042\u0055\u0077\u0025\u004f\u002d\u003b\u0056\u0047\u0057\u005f\u0026\u0059\u0050\u007b\u0030\u0054\u0070\u007b\u005d\u0047\u0053\u0023\u003d\u005f\u0060\u0072\u0067\u005b\u0021\u007c\u0060\u0036\u006b\u0020\u002d\u004f\u0069\u0052\u0077\u0021\u0067\u0079\u0030\u006d\u0032\u0071\u0042\u0060\u0076\u003b\u0039\u0037\u007a\u0049\u003c\u0026\u0022\u0076\u0020\u004c\u004d\u006b\u003d\u0028\u0069\u0039\u0065\u003c\u004e\u0047\u0036\u0036\u007e\u0060\u003c\u0022\u0051\u0071\u0062\u0029\u004a\u006b\u0029\u0055\u004f\u0069\u0031\u0041\u0072\u0050\u003c\u003c\u0047\u006e\u0072\u0054\u0064\u006f\u0047\u0077\u004e\u003c\u007e\u0079\u006c\u0041\u005c\u0064\u002a\u004a\u0066\u0067\u006f\u0068\u0035\u004b\u0031\u005c\u007e\u0044\u004e\u0036\u004a\u0079\u0073\u0054\u0045\u0048\u005f\u0078\u0036\u003c\u004a\u0066\u0057\u005d\u002e\u007a\u0046\u0021\u006d\u0053\u004e\u0035\u0022\u0044\u0071\u0037\u004f\u0062\u0042\u006a\u006b\u0037\u0052\u006d\u0063\u0032\u0047\u0044\u004b\u002b\u0032\u007e\u004c\u005a\u006c\u0056\u0052\u0020\u0066\u0021\u0053\u002e\u003a\u0065\u004b\u0046\u0056\u0040\u002f\u0074\u004d\u0038\u0047\u0075\u005f\u0047\u0033\u007a\u0040\u004b\u0046\u0033\u002d\u0039\u002c\u0048\u0070\u004f\u0037\u0047\u0041\u007a\u007c\u0031\u0029\u0023\u0023\u0077\u0037\u0053\u0043\u0071\u002f\u0020\u003a\u0039\u006f\u005b\u0065\u0064\u0053\u0048\u003f\u003d\u002a\u0041\u0076\u0066\u0062\u005a\u006d\u002d\u0069\u003d\u0079\u0063\u0079\u0069\u003a\u007b\u0029\u003f\u0052\u002d\u0068\u0068\u006e\u0022\u002b\u0077\u002b\u007a\u007e\u0062\u004a\u0059\u006b\u003d\u0055\u003e\u0048\u003f\u0070\u0030\u0060\u0039\u007b\u0039\u0021\u0076\u0055\u0066\u0031\u003d\u004e\u0055\u004f\u0048\u004a\u006b\u0076\u0058\u0049\u006b\u004a\u0055\u0059\u0067\u0024\u007b\u005e\u0025\u0079\u0027\u004d\u0038\u007e\u0070\u002a\u0067\u0064\u003a\u0023\u0023\u006d\u0079\u0075\u0036\u0078\u0061\u0059\u0068\u006f\u003a\u0074\u0071\u005c\u007a\u003a\u0044\u0043\u0038\u0028\u0071\u0062\u005b\u0066\u0044\u0056\u002a\u0037\u0071\u003f\u004b\u0020\u006b\u0055\u0074\u0076\u007d\u0069\u007a\u0076\u005f\u007e\u0076\u0023\u0027\u003c\u0033\u0037\u003f\u0073\u004a\u006d\u0060\u0066\u006a\u0059\u0077\u005c\u007e\u0067\u0059\u0066\u0052\u0038\u004f\u0054\u0070\u003a\u0021\u0020\u004a\u0029\u007d\u0048\u0076\u0037\u003f\u0035\u005b\u0039\u002e\u0067\u0044\u004b\u006a\u006f\u003d\u0025\u0032\u0062\u0062\u0073\u006c\u007e\u0051\u006d\u004c\u002b\u0044\u0075\u003b\u0061\u007d\u0049\u0046\u004b\u0054\u0021\u0020\u0064\u0059\u0057\u006e\u005e\u0045\u003d\u0076\u006e\u0023\u0064\u0051\u005f\u006b\u002f\u006d\u0068\u002d\u0020\u003b\u0076\u0027\u0061\u004e\u0039\u0043\u007c\u0038\u0023\u0076\u0065\u006e\u0040\u0076\u0061\u0028\u004b\u0023\u002a\u0040\u0061\u0057\u002f\u0067\u003a\u0024